# frozen_string_literal: true

# Generated by Descant: acceptance tests.

RSpec.describe TimekeepingRules::EntryRules, ".change_decision with a signed primary role" do
  # "This gives no one more write authority than the monolith already grants through `has_role?`."
  # The monolith refuses a locked edit when the user's primary role is employee.
  it "refuses a raised admin role whose primary role is employee updating a colleague's locked entry" do
    today = Date.new(2026, 3, 10)
    entry = { id: 1, user_id: 2, work_date: today, bill_status: "unbilled", locked: true }
    decide = lambda do |primary_role, entry_value|
      described_class.change_decision(
        caller: :user_delegated, change: { action: :update, bill_status: nil }, role: "admin", primary_role:,
        acting_user_id: 1, entry: entry_value, edit_days: 7, today:
      )
    end

    expect(decide.call("employee", entry)).to eq(:forbidden)
    expect(decide.call("employee", entry.merge(locked: false))).to eq(:ok)
    expect(decide.call("admin", entry)).to eq(:ok)
  end
end
